import Foundation
public actor UserStore {
 private var users: [UUID: User] = [:]
 public func insert(_ user: User) async throws {
  guard users[user.id] == nil else { throw StoreError.duplicate }
  users[user.id] = user
 }
}

export async function loadUsers(client, signal) {
 const response = await client.get('/api/users', { signal });
 return response.items.map(({ id, name }) => ({ id, name: name.trim() }));
}

from dataclasses import dataclass
@dataclass(frozen=True)
class User:
 id: str
 name: str
 def greeting(self) -> str:
  return f"Hello, {self.name}!"

template <typename T>
class Repository final {
public:
 std::optional<T> find(std::string_view id) const {
  const auto it = values_.find(id);
  return it == values_.end() ? std::nullopt : std::optional<T>{it->second};
 }
private:
 std::unordered_map<std::string, T> values_;
};
